/* Ambient declarations for untyped dependencies, SCSS imports, and colors prototype extensions. */

interface String {
  red: string;
  green: string;
  yellow: string;
  blue: string;
  magenta: string;
  cyan: string;
  white: string;
  grey: string;
  gray: string;
  brightBlue: string;
  bold: string;
  dim: string;
}

declare module '*.scss' {
  const css: string;
  export = css;
}

declare module 'colors';

declare module '@babel/core' {
  export interface TransformOptions {
    filename?: string;
    presets?: unknown[];
    plugins?: unknown[];
    sourceMaps?: boolean | 'inline' | 'both';
    [key: string]: unknown;
  }

  export interface BabelFileResult {
    code?: string | null;
    map?: unknown;
    ast?: unknown;
  }

  export function transformAsync(
    code: string,
    options?: TransformOptions,
  ): Promise<BabelFileResult | null>;

  export function transformSync(
    code: string,
    options?: TransformOptions,
  ): BabelFileResult | null;
}

declare module 'xxhash' {
  export function hash(buffer: Buffer, seed: number): number;
}

declare module 'empty-dir' {
  function emptyDir(
    dir: string,
    callback: (error: Error | null, isEmpty: boolean) => void,
  ): void;
  export = emptyDir;
}

declare module 'merge' {
  function merge<T extends Record<string, unknown> = Record<string, unknown>>(
    ...objects: unknown[]
  ): T;
  namespace merge {
    export function recursive<T extends Record<string, unknown> = Record<string, unknown>>(
      ...objects: unknown[]
    ): T;
  }
  export = merge;
}

declare module 'html-minifier-terser' {
  export interface MinifyOptions {
    caseSensitive?: boolean;
    collapseBooleanAttributes?: boolean;
    collapseInlineTagWhitespace?: boolean;
    collapseWhitespace?: boolean;
    conservativeCollapse?: boolean;
    decodeEntities?: boolean;
    html5?: boolean;
    ignoreCustomComments?: RegExp[];
    ignoreCustomFragments?: RegExp[];
    includeAutoGeneratedTags?: boolean;
    keepClosingSlash?: boolean;
    minifyCSS?: boolean | Record<string, unknown>;
    minifyJS?: boolean | Record<string, unknown>;
    minifyURLs?: boolean;
    preserveLineBreaks?: boolean;
    preventAttributesEscaping?: boolean;
    processConditionalComments?: boolean;
    quoteCharacter?: string;
    removeAttributeQuotes?: boolean;
    removeComments?: boolean;
    removeEmptyAttributes?: boolean;
    removeEmptyElements?: boolean;
    removeOptionalTags?: boolean;
    removeRedundantAttributes?: boolean;
    removeScriptTypeAttributes?: boolean;
    removeStyleLinkTypeAttributes?: boolean;
    removeTagWhitespace?: boolean;
    sortAttributes?: boolean;
    sortClassName?: boolean;
    trimCustomFragments?: boolean;
    useShortDoctype?: boolean;
  }

  export function minify(value: string, options?: MinifyOptions): Promise<string>;
}
